css:
/* From Uiverse.io by andrew-demchenk0 - Tags: radio, select, radio-buttons, options  */
.__UIV_SCOPE__ .wrapper {
  --font-color-dark: #323232;
  --font-color-light: #FFF;
  --bg-color: #fff;
  --main-color: #323232;
  position: relative;
  width: 250px;
  height: 36px;
  background-color: var(--bg-color);
  border: 2px solid var(--main-color);
  border-radius: 34px;
  display: flex;
  flex-direction: row;
  box-shadow: 4px 4px var(--main-color);
}

.__UIV_SCOPE__ .option {
  width: 80.5px;
  height: 28px;
  position: relative;
  top: 2px;
  left: 2px;
}

.__UIV_SCOPE__ .input {
  width: 100%;
  height: 100%;
  position: absolute;
  left: 0;
  top: 0;
  appearance: none;
  cursor: pointer;
}

.__UIV_SCOPE__ .btn {
  width: 100%;
  height: 100%;
  background-color: var(--bg-color);
  border-radius: 50px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .span {
  color: var(--font-color-dark);
}

.__UIV_SCOPE__ .input:checked + .btn {
  background-color: var(--main-color);
}

.__UIV_SCOPE__ .input:checked + .btn .span {
  color: var(--font-color-light);
}
